"use client";

import * as React from "react";
import { OTPField as BaseOTPField } from "@base-ui/react/otp-field";

import { cn } from "@/lib/utils";
import { TextMorph } from "@/registry/default/text-morph/text-morph";

import "./otp-field.css";

function OTPField({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseOTPField.Root>) {
  return (
    <BaseOTPField.Root
      data-slot="otp-field"
      className={cn(
        "group/otp-field relative flex items-center gap-2",
        className,
      )}
      {...props}
    >
      {children}
      {/* One focus ring for the field, anchored to the focused slot in CSS. */}
      <span
        aria-hidden="true"
        data-slot="otp-field-indicator"
        className="otp-field-indicator outline-ring/50 group-data-[invalid]/otp-field:outline-destructive/50 outline-2 outline-offset-2 outline-solid"
      />
    </BaseOTPField.Root>
  );
}

export type OTPFieldInputProps = Omit<
  React.ComponentProps<typeof BaseOTPField.Input>,
  "className" | "style" | "render"
> & {
  /** Applied to the visible slot around the input. */
  className?: string;
  style?: React.CSSProperties;
  variant?: "default" | "elevated";
};

function OTPFieldInput({
  className,
  style,
  variant = "default",
  ...props
}: OTPFieldInputProps) {
  return (
    <BaseOTPField.Input
      data-slot="otp-field-input"
      {...props}
      render={(inputProps, state) => {
        const invalid =
          inputProps["aria-invalid"] === true ||
          inputProps["aria-invalid"] === "true";
        // A masked slot shows a dot instead of the character.
        const masked = inputProps.type === "password";
        const shown = masked && state.value ? "•" : state.value;

        return (
          <span
            data-slot="otp-field-slot"
            data-filled={state.filled ? "" : undefined}
            data-invalid={invalid ? "" : undefined}
            data-disabled={state.disabled ? "" : undefined}
            className={cn(
              // Base styling
              "relative flex h-10 w-10 cursor-text items-center justify-center rounded-[var(--otp-field-radius,var(--radius-lg))] border bg-clip-padding text-base font-medium tabular-nums sm:h-9 sm:w-9 md:text-sm",
              variant === "default" ? "bg-input" : "bg-input-elevated",
              // Invalid state (the focused slot's ring comes from the root)
              "data-[invalid]:outline-destructive/50 data-[invalid]:outline-2 data-[invalid]:outline-offset-2 data-[invalid]:outline-solid",
              // Disabled state
              "data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:opacity-60",
              className,
            )}
            style={style}
          >
            {/* The real input fills the slot, its own text and selection
                hidden: the character is drawn above. */}
            <input
              {...inputProps}
              className={cn(
                "absolute inset-0 size-full cursor-text rounded-[inherit] bg-transparent text-center outline-none [font:inherit]",
                // Text and caret color are set in otp-field.css.
                "selection:bg-transparent",
                "placeholder:text-muted-foreground placeholder:[-webkit-text-fill-color:currentColor] focus:placeholder:text-transparent",
              )}
            />
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 flex items-center justify-center"
            >
              <TextMorph
                value={shown}
                className={cn(
                  "otp-field-glyph",
                  masked && "text-[1.5em] leading-none",
                )}
                mode="morph"
                duration={380}
                options={{ trend: "auto" }}
              />
            </span>
          </span>
        );
      }}
    />
  );
}

function OTPFieldSeparator({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseOTPField.Separator>) {
  return (
    <BaseOTPField.Separator
      data-slot="otp-field-separator"
      className={cn("text-muted-foreground", className)}
      {...props}
    >
      {children ?? <SeparatorDash />}
    </BaseOTPField.Separator>
  );
}

function OTPFieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="otp-field-group"
      className={cn("flex items-center gap-2", className)}
      {...props}
    />
  );
}

function SeparatorDash(props: React.ComponentProps<"svg">) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 8 2"
      width="8"
      height="2"
      fill="none"
      {...props}
    >
      <path
        d="M1 1H7"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  );
}

export { OTPField, OTPFieldInput, OTPFieldSeparator, OTPFieldGroup };

"use client";

import * as React from "react";

export interface UseInvalidFeedbackOptions {
  /**
   * Duration in ms before the shake animation clears.
   * @default 400
   */
  duration?: number;
}

export interface UseInvalidFeedbackReturn {
  /**
   * The shake className for the field, or `undefined` when no feedback is
   * active. Pass it to `OTPField`: the focused slot and the focus ring shake
   * together.
   *
   * @example
   * ```tsx
   * <OTPField className={invalidFeedback.className} />
   * ```
   */
  className: string | undefined;

  /**
   * Clears invalid feedback when the value changes.
   * Wire to OTPField's `onValueChange`.
   *
   * @example
   * ```tsx
   * <OTPField onValueChange={invalidFeedback.handleValueChange} />
   * ```
   */
  handleValueChange: () => void;

  /**
   * Triggers invalid feedback animation and status message.
   * Wire to OTPField's `onValueInvalid`.
   *
   * @example
   * ```tsx
   * <OTPField onValueInvalid={invalidFeedback.handleValueInvalid} />
   * ```
   */
  handleValueInvalid: (value: string) => void;

  /**
   * Screen reader status message. Render inside an `aria-live` region.
   *
   * @example
   * ```tsx
   * <span aria-live="polite" className="sr-only">
   *   {invalidFeedback.statusMessage}
   * </span>
   * ```
   */
  statusMessage: string;
}

// Alternated so a repeat invalid entry restarts the animation.
const SHAKE_CLASS_A = "otp-field-shake-a";
const SHAKE_CLASS_B = "otp-field-shake-b";

/**
 * Hook that manages shake animation and screen reader feedback
 * for invalid OTP input.
 *
 * @example
 * ```tsx
 * const invalidFeedback = useInvalidFeedback();
 *
 * <OTPField
 *   length={6}
 *   validationType="none"
 *   normalizeValue={normalizeTierCode}
 *   className={invalidFeedback.className}
 *   onValueChange={invalidFeedback.handleValueChange}
 *   onValueInvalid={invalidFeedback.handleValueInvalid}
 * >
 *   {Array.from({ length: 6 }, (_, index) => (
 *     <OTPFieldInput key={index} />
 *   ))}
 * </OTPField>
 * <span aria-live="polite" className="sr-only">
 *   {invalidFeedback.statusMessage}
 * </span>
 * ```
 */
export function useInvalidFeedback(
  options: UseInvalidFeedbackOptions = {},
): UseInvalidFeedbackReturn {
  const { duration = 400 } = options;

  const [invalidPulse, setInvalidPulse] = React.useState(0);
  const [statusMessage, setStatusMessage] = React.useState("");
  const invalidTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const skipClearOnNextValueChangeRef = React.useRef(false);

  React.useEffect(() => {
    return () => {
      if (invalidTimeoutRef.current != null) {
        clearTimeout(invalidTimeoutRef.current);
      }
    };
  }, []);

  function handleValueChange() {
    if (skipClearOnNextValueChangeRef.current) {
      skipClearOnNextValueChangeRef.current = false;
      return;
    }

    if (invalidTimeoutRef.current != null) {
      clearTimeout(invalidTimeoutRef.current);
      invalidTimeoutRef.current = null;
    }
    setInvalidPulse(0);
    setStatusMessage("");
  }

  function handleValueInvalid(value: string) {
    skipClearOnNextValueChangeRef.current = true;
    setInvalidPulse((current) => current + 1);
    setStatusMessage(`Unsupported characters were ignored from ${value}.`);

    if (invalidTimeoutRef.current != null) {
      clearTimeout(invalidTimeoutRef.current);
    }

    invalidTimeoutRef.current = setTimeout(() => {
      invalidTimeoutRef.current = null;
      setInvalidPulse(0);
    }, duration);
  }

  const className =
    invalidPulse === 0
      ? undefined
      : invalidPulse % 2 === 0
        ? SHAKE_CLASS_B
        : SHAKE_CLASS_A;

  return {
    className,
    handleValueChange,
    handleValueInvalid,
    statusMessage,
  };
}

/* -------------------------------------------------------------------------------------------------
 * Sliding focus ring, in CSS anchor positioning.
 *
 * The focused slot takes the anchor name and the ring is placed on it, so
 * moving focus moves the anchor and the ring's inset transitions to the new
 * slot. `anchor-scope` keeps each field's name to itself. The ring is
 * display: none while the field has no focus, so it has no earlier position
 * to slide from: it appears on the slot and settles in (@starting-style).
 * Without anchor positioning, each slot draws its own ring instead.
 * -------------------------------------------------------------------------------------------------*/

[data-slot="otp-field"] {
  anchor-scope: --otp-field-slot;
}

[data-slot="otp-field-slot"]:focus-within {
  anchor-name: --otp-field-slot;
}

.otp-field-indicator {
  display: none;
  position: absolute;
  position-anchor: --otp-field-slot;
  top: anchor(top);
  left: anchor(left);
  width: anchor-size(width);
  height: anchor-size(height);
  z-index: 1;
  border-radius: var(--otp-field-radius, var(--radius-lg));
  pointer-events: none;
  transition:
    top 280ms cubic-bezier(0.19, 1, 0.22, 1),
    left 280ms cubic-bezier(0.19, 1, 0.22, 1),
    width 280ms cubic-bezier(0.19, 1, 0.22, 1),
    height 280ms cubic-bezier(0.19, 1, 0.22, 1),
    scale 240ms cubic-bezier(0.19, 1, 0.22, 1),
    opacity 150ms ease-out,
    outline-color 150ms ease-out;
}

[data-slot="otp-field"]:focus-within > .otp-field-indicator {
  display: block;

  @starting-style {
    opacity: 0;
    scale: 1.12;
  }
}

/* Every anchor feature the ring uses, or none: a partial implementation
 * would leave it unsized or tied to another field. */
@supports not (
  (anchor-name: --otp-field-slot) and (anchor-scope: --otp-field-slot) and
    (width: anchor-size(width))
) {
  .otp-field-indicator {
    display: none !important;
  }

  [data-slot="otp-field-slot"]:focus-within {
    outline: 2px solid
      color-mix(in oklab, var(--color-ring, Highlight) 50%, transparent);
    outline-offset: 2px;
  }

  .otp-field-shake-a [data-slot="otp-field-slot"]:focus-within,
  .otp-field-shake-b [data-slot="otp-field-slot"]:focus-within {
    outline-color: color-mix(
      in oklab,
      var(--color-destructive, red) 80%,
      transparent
    );
  }
}

/* -------------------------------------------------------------------------------------------------
 * The input's own text is hidden (the character is drawn above it by
 * TextMorph). Its native caret stays in an empty slot, where it sits centred,
 * and hides in a filled one, where it would sit beside the invisible
 * character rather than the drawn one. Unlayered and specific, so a page's
 * global `input { caret-color }` can't override it.
 * -------------------------------------------------------------------------------------------------*/

[data-slot="otp-field-slot"] > input[data-slot="otp-field-input"] {
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--color-primary, CanvasText);
}

[data-slot="otp-field-slot"][data-filled] > input[data-slot="otp-field-input"] {
  caret-color: transparent;
}

/* Forced colors would repaint the input's own text over the drawn one. */
@media (forced-colors: active) {
  [data-slot="otp-field-slot"] > input[data-slot="otp-field-input"] {
    forced-color-adjust: none;
  }
}

/* A filled slot selects its character on focus (typing replaces it): the
 * drawn character carries the selection, since the input's is invisible. */
.otp-field-glyph {
  border-radius: 3px;
  padding-inline: 1px;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out;
}

[data-slot="otp-field-slot"][data-filled]:focus-within .otp-field-glyph {
  background-color: var(--color-primary, Highlight);
  color: var(--color-primary-foreground, HighlightText);
}

/* -------------------------------------------------------------------------------------------------
 * Invalid-input shake.
 *
 * Paired identical keyframes. CSS animations don't restart when re-applied to
 * the same element with the same animation-name, so on each invalid OTP entry
 * we alternate between the two classes to force the browser to treat it as a
 * new animation and replay the shake. Keep both bodies in sync. The class
 * sits on the field (useInvalidFeedback); the focused slot and the ring shake
 * together with `transform`, which leaves the anchor where it is (moving the
 * slot's layout box would start the ring's slide transition instead).
 * -------------------------------------------------------------------------------------------------*/

.otp-field-shake-a > .otp-field-indicator,
.otp-field-shake-b > .otp-field-indicator {
  outline-color: color-mix(
    in oklab,
    var(--color-destructive, red) 80%,
    transparent
  );
}

.otp-field-shake-a > .otp-field-indicator,
.otp-field-shake-a [data-slot="otp-field-slot"]:focus-within {
  animation: otp-field-shake-a 180ms ease-in-out;
}

.otp-field-shake-b > .otp-field-indicator,
.otp-field-shake-b [data-slot="otp-field-slot"]:focus-within {
  animation: otp-field-shake-b 180ms ease-in-out;
}

@keyframes otp-field-shake-a {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-4px);
  }
  75% {
    transform: translateX(4px);
  }
}

@keyframes otp-field-shake-b {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-4px);
  }
  75% {
    transform: translateX(4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .otp-field-indicator {
    transition:
      opacity 150ms ease-out,
      outline-color 150ms ease-out;
  }

  [data-slot="otp-field"]:focus-within > .otp-field-indicator {
    @starting-style {
      scale: 1;
    }
  }

  /* The ring still turns red. */
  [data-slot="otp-field"] > .otp-field-indicator,
  [data-slot="otp-field-slot"] {
    animation: none !important;
  }
}
